// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO;
using Shared.DTO.Customer;
using Shared.DTO.Departments;
using Shared.DTO.Employee;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Employee
{
    public partial class Edit
    {

        [Parameter]
        public string id { get; set; }

        EmployeeDto employee { get; set; } = new EmployeeDto();
        private List<SelectOptionDto>? DepartmentOptions = new List<SelectOptionDto>();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected async override Task OnInitializedAsync()
        {
            employee = await Http.GetFromJsonAsync<EmployeeDto>("api/Employees/" + id);
            DepartmentOptions = await Http.GetFromJsonAsync<List<SelectOptionDto>>("api/Departments/getselectoption");
        }

        protected async Task EditDepartment()
        {
            var response = await Http.PutAsJsonAsync("api/Employees/" + id, employee);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/Employee");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }

        }
    }
}
